/* VEIL core — local crypto studio. Envelope format, key derivation, ML-KEM integration and the
   one-time vault are unchanged from VEIL 2.2; only presentation calls go through VeilUI. */
(()=>{'use strict';
const E=new TextEncoder(),D=new TextDecoder('utf-8',{fatal:true});const $=id=>document.getElementById(id);const MAX_FILE=24*1024*1024,MAX_ENVELOPE=45*1024*1024,MIN_ROUNDS=100000,MAX_ROUNDS=1000000;
const SUITES={
 'AES-256-GCM':{bits:256,mode:'GCM'},'AES-192-GCM':{bits:192,mode:'GCM'},'AES-128-GCM':{bits:128,mode:'GCM'},
 'AES-256-OCB':{bits:256,mode:'OCB'},'AES-128-OCB':{bits:128,mode:'OCB'},
 'AES-256-CBC-HMAC':{bits:256,mode:'CBC-HMAC'},'AES-256-CTR-HMAC':{bits:256,mode:'CTR-HMAC'},
 'CHACHA20-POLY1305':{bits:256,mode:'CHACHA'},
 'PQ-ML-KEM-768':{bits:256,mode:'PQ',kem:'ML-KEM-768'},'PQ-ML-KEM-1024':{bits:256,mode:'PQ',kem:'ML-KEM-1024'},'PQ-MLKEM768-X25519':{bits:256,mode:'PQ',kem:'MLKEM768-X25519'}
};
const KEMS=['ML-KEM-768','ML-KEM-1024','MLKEM768-X25519'];const kemErrors=new Map();const KEM_SIZES={'ML-KEM-768':{public:1184,capsule:1088,seed:64},'ML-KEM-1024':{public:1568,capsule:1568,seed:64},'MLKEM768-X25519':{public:1216,capsule:1120,seed:32}};const kemAvailable=new Map();let encryptFile=null,encryptedOutput='',encryptedKind='text',decryptedOutput=null,tab='text',toastTimer=null;
const subtle=()=>{if(!globalThis.crypto?.subtle||!globalThis.crypto?.getRandomValues)throw Error('WebCrypto indisponível neste visualizador. Abra o HTML em navegador seguro que execute JavaScript.');return globalThis.crypto.subtle;};
const random=n=>{const a=new Uint8Array(n);crypto.getRandomValues(a);return a;};
const concat=(...arrays)=>{const length=arrays.reduce((n,x)=>n+x.length,0),o=new Uint8Array(length);let j=0;for(const x of arrays){o.set(x,j);j+=x.length}return o};
const u8=v=>v instanceof Uint8Array?v:new Uint8Array(v);
const b64=buf=>{const bytes=u8(buf);let s='';for(let i=0;i<bytes.length;i+=16384){s+=String.fromCharCode(...bytes.subarray(i,i+16384))}return btoa(s).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'')};
const unb64=s=>{if(typeof s!=='string'||s.length>MAX_ENVELOPE*2||!/^[A-Za-z0-9_-]+$/.test(s))throw Error('Base64URL inválido.');const norm=s.replace(/-/g,'+').replace(/_/g,'/');const binary=atob(norm.padEnd(Math.ceil(norm.length/4)*4,'='));return Uint8Array.from(binary,c=>c.charCodeAt(0));};
const cleanFilename=n=>String(n||'arquivo').replace(/[\\/\x00-\x1f\x7f:*?"<>|]/g,'_').slice(0,180)||'arquivo';
const asText=v=>D.decode(v),asBytes=v=>E.encode(v);
const warning=(id,msg,type='error')=>VeilUI.notice(id,msg,type);
const hideWarning=id=>$(id).classList.add('hidden');
const inform=(txt)=>VeilUI.toast(txt);
const detectInput=(value)=>{
 const s=String(value||'').trim();
 if(!s)return {type:'empty',label:'Cole um código para identificar.'};
 if(s.startsWith('VEIL1.')){try{return {type:'veil',obj:parseEnvelope(s)}}catch(e){return{type:'invalid',label:'VEIL v1 reconhecido, porém inválido: '+e.message}}}
 if(s.startsWith('VEILONCE1.'))return {type:'external',label:'Código VEIL de leitura única por servidor LAN (VEILONCE1). Esta versão não inclui o servidor LAN e não abre esse código; ele não contém a mensagem cifrada.'};
 if(s.startsWith('PQPK1.'))return {type:'key',label:'Chave pública pós-quântica VEIL (PQPK1). Não é um envelope de mensagem.'};
 if(s.startsWith('PQSK1.'))return {type:'key',label:'Chave privada pós-quântica VEIL (PQSK1), protegida por senha.'};
 if(/^-----BEGIN PGP MESSAGE-----/.test(s))return {type:'external',label:'OpenPGP ASCII Armor detectado. Algoritmo interno depende dos pacotes PGP; não é possível inferi-lo só pelo cabeçalho. VEIL não descriptografa OpenPGP.'};
 if(/^age-encryption.org\/v1(?:\s|$)/.test(s)||/^-----BEGIN AGE ENCRYPTED FILE-----/.test(s))return {type:'external',label:'Formato age reconhecido. Pode usar destinatários X25519 ou outros tipos; a cifra exata depende do payload. Não é um envelope VEIL.'};
 if(/^-----BEGIN ENCRYPTED PRIVATE KEY-----/.test(s))return{type:'external',label:'PEM PKCS#8: chave privada criptografada. É necessário um parser ASN.1 para determinar os parâmetros internos; VEIL não abre essa chave.'};
 if(/^-----BEGIN OPENSSH PRIVATE KEY-----/.test(s))return{type:'external',label:'Formato de chave privada OpenSSH reconhecido. O cabeçalho sozinho não revela se existe criptografia da chave.'};
 if(/^-----BEGIN (?:RSA |EC |DSA )?PRIVATE KEY-----/.test(s))return{type:'external',label:'Chave privada em formato PEM detectada. Pode ou não estar protegida: não presuma criptografia.'};
 if(/^-----BEGIN [A-Z0-9 _-]+-----/.test(s))return{type:'external',label:'Armadura PEM/ASCII reconhecida. Isso identifica um contêiner textual, não necessariamente uma cifra.'};
 if(/^gAAAAA[A-Za-z0-9_-]{50,}={0,2}$/.test(s))return{type:'external',label:'Possível token Fernet por assinatura textual; classificação heurística. VEIL não decifra tokens Fernet.'};
 if(/^Salted__/.test(s)||/^U2FsdGVkX1/.test(s))return{type:'external',label:'OpenSSL enc (cabeçalho Salted__) provável. A cifra, o KDF e o digest não são recuperáveis com certeza somente desse marcador; VEIL não abre esse formato.'};
 if(s.split('.').length===5 && /^[A-Za-z0-9_-]+(?:\.[A-Za-z0-9_-]*){4}$/.test(s)){
  try{const h=JSON.parse(asText(unb64(s.split('.')[0])));if(h&&typeof h.alg==='string'&&typeof h.enc==='string')return{type:'external',label:'JWE Compact detectado. Gerenciamento de chave: '+h.alg+'; cifra de conteúdo declarada: '+h.enc+'. Estes valores vêm do cabeçalho e não estão autenticados nesta inspeção. VEIL não abre JWE.'};}catch{}
 }
 if(/^(?:[a-f0-9]{2})+$/i.test(s)&&s.length>=16)return{type:'unknown',label:'Texto hexadecimal provável. Hex é codificação, não identifica algoritmo de criptografia.'};
 if(/^[A-Za-z0-9+/=\r\n]+$/.test(s)&&s.length>=16)return{type:'unknown',label:'Base64 provável. Sem estrutura ou metadados confiáveis, não é possível identificar a cifra.'};
 return{type:'unknown',label:'Formato desconhecido. Conteúdo sem metadados não permite identificar a cifra com segurança.'};
};
const parseEnvelope=code=>{if(!code.startsWith('VEIL1.'))throw Error('Prefixo VEIL1. ausente.');const data=unb64(code.slice(6));if(data.length>MAX_ENVELOPE)throw Error('Envelope excede o limite de tamanho.');let obj;try{obj=JSON.parse(asText(data))}catch{throw Error('Estrutura JSON inválida.')}if(!obj||typeof obj!=='object'||Array.isArray(obj)||obj.v!==1||typeof obj.suite!=='string'||!Object.prototype.hasOwnProperty.call(SUITES,obj.suite))throw Error('Versão ou algoritmo não suportado.');const allowed=new Set(['v','suite','kdf','rounds','salt','iv','kind','pq','ct','mac']);if(Object.keys(obj).some(k=>!allowed.has(k)))throw Error('Campo de envelope desconhecido.');if(!['text','file','private-key'].includes(obj.kind))throw Error('Tipo de conteúdo inválido.');if(obj.kdf!=='SHA-256'&&obj.kdf!=='SHA-512')throw Error('KDF não suportado.');if(!Number.isSafeInteger(obj.rounds)||obj.rounds<MIN_ROUNDS||obj.rounds>MAX_ROUNDS)throw Error('Custo PBKDF2 inválido.');if(typeof obj.salt!=='string'||unb64(obj.salt).length!==16)throw Error('Salt inválido.');if(typeof obj.iv!=='string'||unb64(obj.iv).length!==(SUITES[obj.suite].mode==='CBC-HMAC'||SUITES[obj.suite].mode==='CTR-HMAC'?16:12))throw Error('Nonce/IV inválido.');if(typeof obj.ct!=='string'||obj.ct.length>MAX_ENVELOPE*2||unb64(obj.ct).length<16)throw Error('Dados cifrados ausentes ou inválidos.');if(SUITES[obj.suite].mode==='PQ'){if(!obj.pq||typeof obj.pq!=='object'||Array.isArray(obj.pq)||Object.keys(obj.pq).some(k=>!['kem','capsule'].includes(k))||obj.pq.kem!==SUITES[obj.suite].kem||typeof obj.pq.capsule!=='string'||unb64(obj.pq.capsule).length!==KEM_SIZES[obj.pq.kem].capsule)throw Error('Cápsula pós-quântica inválida.')}else if(obj.pq!==undefined)throw Error('Metadados pós-quânticos inesperados.');if(['CBC-HMAC','CTR-HMAC'].includes(SUITES[obj.suite].mode)){if(typeof obj.mac!=='string'||unb64(obj.mac).length!==32)throw Error('HMAC obrigatório ausente ou inválido.');}else if(obj.mac!==undefined)throw Error('HMAC inesperado nesta cifra.');return obj;};
const aadFor=o=>{const {v,suite,kdf,rounds,salt,iv,kind,pq}=o;return asBytes(JSON.stringify({v,suite,kdf,rounds,salt,iv,kind,...(pq?{pq}:{})}));};
async function pbk(password,salt,iterations,hash){const root=await subtle().importKey('raw',asBytes(password),'PBKDF2',false,['deriveBits']);return new Uint8Array(await subtle().deriveBits({name:'PBKDF2',salt,iterations,hash},root,256));}
async function expand(secret,salt,info,bits){const key=await subtle().importKey('raw',secret,'HKDF',false,['deriveBits']);return new Uint8Array(await subtle().deriveBits({name:'HKDF',hash:'SHA-256',salt,info:asBytes(info)},key,bits));}
const qAlg=alg=>({name:alg});
function equalBytes(a,b){a=u8(a);b=u8(b);if(a.length!==b.length)return false;let diff=0;for(let i=0;i<a.length;i++)diff|=a[i]^b[i];return diff===0;}
// Test actual key exchange and seed import, not merely the presence of an API method.
async function pqSupport(alg){if(!KEMS.includes(alg))return false;if(kemAvailable.has(alg))return kemAvailable.get(alg);let ok=false,seed;try{const s=subtle();if(typeof s.encapsulateBits!=='function'||typeof s.decapsulateBits!=='function')throw Error('WebCrypto encapsulateBits/decapsulateBits ausente');const pair=await s.generateKey(qAlg(alg),true,['encapsulateBits','decapsulateBits']);const publicBytes=u8(await s.exportKey('raw-public',pair.publicKey));seed=u8(await s.exportKey('raw-seed',pair.privateKey));if(publicBytes.length!==KEM_SIZES[alg].public||seed.length!==KEM_SIZES[alg].seed)throw Error('Tamanho inesperado da chave');const publicKey=await s.importKey('raw-public',publicBytes,qAlg(alg),false,['encapsulateBits']);const privateKey=await s.importKey('raw-seed',seed,qAlg(alg),false,['decapsulateBits']);const wrap=await s.encapsulateBits(qAlg(alg),publicKey);const shared=await s.decapsulateBits(qAlg(alg),privateKey,wrap.ciphertext);if(u8(wrap.ciphertext).length!==KEM_SIZES[alg].capsule||u8(wrap.sharedKey).length!==32||!equalBytes(wrap.sharedKey,shared))throw Error('Encapsulamento ou restauração inválidos');ok=true;}catch(e){kemErrors.set(alg,(e?.name||'Erro')+': '+(e?.message||'API indisponível'));}finally{if(seed)seed.fill(0);}kemAvailable.set(alg,ok);return ok;}
async function openPublicKey(str,wanted){let item;try{if(!str.trim().startsWith('PQPK1.'))throw Error();item=JSON.parse(asText(unb64(str.trim().slice(6))))}catch{throw Error('Chave pública inválida. Cole o texto PQPK1. completo.')}if(item.v!==1||item.kem!==wanted||typeof item.key!=='string')throw Error('A chave pública não corresponde ao algoritmo escolhido.');let raw=unb64(item.key);if(raw.length!==KEM_SIZES[wanted].public)throw Error('Tamanho de chave pública inválido.');return subtle().importKey('raw-public',raw,qAlg(wanted),false,['encapsulateBits']);}
async function protect(plaintext,opts){const {password,suite,kdf='SHA-256',rounds=600000,kind='text',pub=''}=opts;if(typeof suite!=='string'||!Object.prototype.hasOwnProperty.call(SUITES,suite))throw Error('Algoritmo desconhecido.');if(!['text','file','private-key'].includes(kind))throw Error('Tipo de conteúdo inválido.');if(!password||password.length<10)throw Error('A senha precisa ter ao menos 10 caracteres.');if(!Number.isSafeInteger(rounds)||rounds<MIN_ROUNDS||rounds>MAX_ROUNDS)throw Error('Custo PBKDF2 inválido.');const mode=SUITES[suite].mode,salt=random(16),iv=random(['CBC-HMAC','CTR-HMAC'].includes(mode)?16:12),header={v:1,suite,kdf,rounds,salt:b64(salt),iv:b64(iv),kind};let pqSecret=null;
if(mode==='PQ'){const kem=SUITES[suite].kem;if(!(await pqSupport(kem)))throw Error('Seu navegador não oferece WebCrypto '+kem+'. Use AES-256-GCM ou navegador com suporte a ML-KEM.');const pk=await openPublicKey(pub,kem);const result=await subtle().encapsulateBits(qAlg(kem),pk);pqSecret=u8(result.sharedKey);header.pq={kem,capsule:b64(result.ciphertext)};}
let raw=await pbk(password,salt,rounds,kdf);if(pqSecret)raw=concat(raw,pqSecret);const aad=aadFor(header),buffer=u8(plaintext);let ciphertext,mac;
if(mode==='GCM'||mode==='PQ'){const keyBytes=await expand(raw,salt,'VEIL1|'+suite,SUITES[suite].bits),key=await subtle().importKey('raw',keyBytes,{name:'AES-GCM'},false,['encrypt']);ciphertext=u8(await subtle().encrypt({name:'AES-GCM',iv,additionalData:aad,tagLength:128},key,buffer));}
else if(mode==='OCB'){const keyBytes=await expand(raw,salt,'VEIL1|'+suite,SUITES[suite].bits),key=await subtle().importKey('raw-secret',keyBytes,{name:'AES-OCB'},false,['encrypt']);ciphertext=u8(await subtle().encrypt({name:'AES-OCB',iv,additionalData:aad,tagLength:128},key,buffer));}
 else if(mode==='CHACHA'){const keyBytes=await expand(raw,salt,'VEIL1|'+suite,256),key=await subtle().importKey('raw-secret',keyBytes,{name:'ChaCha20-Poly1305'},false,['encrypt']);ciphertext=u8(await subtle().encrypt({name:'ChaCha20-Poly1305',iv,additionalData:aad,tagLength:128},key,buffer));}
else{const keys=await expand(raw,salt,'VEIL1|'+suite,512);const key=await subtle().importKey('raw',keys.slice(0,32),{name:mode==='CBC-HMAC'?'AES-CBC':'AES-CTR'},false,['encrypt']);ciphertext=u8(await subtle().encrypt(mode==='CBC-HMAC'?{name:'AES-CBC',iv}:{name:'AES-CTR',counter:iv,length:64},key,buffer));const h=await subtle().importKey('raw',keys.slice(32),{name:'HMAC',hash:'SHA-256'},false,['sign']);mac=b64(await subtle().sign('HMAC',h,concat(asBytes('VEIL1-MAC\0'),aad,ciphertext)));}
const body={...header,ct:b64(ciphertext),...(mac?{mac}:{})};return 'VEIL1.'+b64(asBytes(JSON.stringify(body)));
}
async function recover(code,password,privateEnvelope='',privatePassword=''){const obj=parseEnvelope(code);if(!password)throw Error('Digite a senha do envelope.');const desc=SUITES[obj.suite],mode=desc.mode,iv=unb64(obj.iv),salt=unb64(obj.salt),aad=aadFor(obj),ct=unb64(obj.ct);let raw=await pbk(password,salt,obj.rounds,obj.kdf);
if(mode==='PQ'){if(!await pqSupport(desc.kem))throw Error('Este navegador não suporta '+desc.kem+' para abrir o envelope.');if(!privateEnvelope.trim())throw Error('Cole a chave privada protegida PQSK1. do destinatário.');const privateKey=await unlockPrivate(privateEnvelope,privatePassword||password,desc.kem);const shared=u8(await subtle().decapsulateBits(qAlg(desc.kem),privateKey,unb64(obj.pq.capsule)));raw=concat(raw,shared);}
try{let plain;if(mode==='GCM'||mode==='PQ'){const keyBytes=await expand(raw,salt,'VEIL1|'+obj.suite,desc.bits),key=await subtle().importKey('raw',keyBytes,{name:'AES-GCM'},false,['decrypt']);plain=await subtle().decrypt({name:'AES-GCM',iv,additionalData:aad,tagLength:128},key,ct);}
else if(mode==='OCB'){const keyBytes=await expand(raw,salt,'VEIL1|'+obj.suite,desc.bits),key=await subtle().importKey('raw-secret',keyBytes,{name:'AES-OCB'},false,['decrypt']);plain=await subtle().decrypt({name:'AES-OCB',iv,additionalData:aad,tagLength:128},key,ct);}
 else if(mode==='CHACHA'){const keyBytes=await expand(raw,salt,'VEIL1|'+obj.suite,256),key=await subtle().importKey('raw-secret',keyBytes,{name:'ChaCha20-Poly1305'},false,['decrypt']);plain=await subtle().decrypt({name:'ChaCha20-Poly1305',iv,additionalData:aad,tagLength:128},key,ct);}
else{const keys=await expand(raw,salt,'VEIL1|'+obj.suite,512),h=await subtle().importKey('raw',keys.slice(32),{name:'HMAC',hash:'SHA-256'},false,['verify']);const ok=await subtle().verify('HMAC',h,unb64(obj.mac),concat(asBytes('VEIL1-MAC\0'),aad,ct));if(!ok)throw Error('AUTH_FAILED');const key=await subtle().importKey('raw',keys.slice(0,32),{name:mode==='CBC-HMAC'?'AES-CBC':'AES-CTR'},false,['decrypt']);plain=await subtle().decrypt(mode==='CBC-HMAC'?{name:'AES-CBC',iv}:{name:'AES-CTR',counter:iv,length:64},key,ct);}
return{obj,bytes:u8(plain)};
}catch{throw Error('Falha de autenticação: senha incorreta, chave errada ou envelope modificado.');}}
async function unlockPrivate(value,password,wanted){let data;try{if(!value.trim().startsWith('PQSK1.'))throw Error();data=JSON.parse(asText(unb64(value.trim().slice(6))))}catch{throw Error('Formato de chave privada inválido.')}if(data.v!==1||data.kem!==wanted||typeof data.envelope!=='string')throw Error('Chave privada não corresponde ao algoritmo do envelope.');const result=await recover(data.envelope,password);if(result.obj.kind!=='private-key'||result.bytes.length!==KEM_SIZES[wanted].seed)throw Error('Conteúdo de chave privada inesperado.');return subtle().importKey('raw-seed',result.bytes,qAlg(wanted),false,['decapsulateBits']);}
async function generateKeys(alg,password,rounds=600000){if(password.length<10)throw Error('Use uma senha de pelo menos 10 caracteres para a chave privada.');if(!await pqSupport(alg))throw Error('ML-KEM não está disponível neste navegador.');const pair=await subtle().generateKey(qAlg(alg),true,['encapsulateBits','decapsulateBits']);const publicRaw=new Uint8Array(await subtle().exportKey('raw-public',pair.publicKey)),seed=new Uint8Array(await subtle().exportKey('raw-seed',pair.privateKey));let wrapped;try{wrapped=await protect(seed,{password,suite:'AES-256-GCM',kdf:'SHA-256',rounds,kind:'private-key'});}finally{seed.fill(0)}return{pub:'PQPK1.'+b64(asBytes(JSON.stringify({v:1,kem:alg,key:b64(publicRaw)}))),priv:'PQSK1.'+b64(asBytes(JSON.stringify({v:1,kem:alg,envelope:wrapped})))};}
const packFile=async file=>{const meta=asBytes(JSON.stringify({n:cleanFilename(file.name),m:file.type||'application/octet-stream'}));if(meta.length>65535)throw Error('Metadados do arquivo são muito longos.');const raw=new Uint8Array(await file.arrayBuffer());return concat(asBytes('VF1'),new Uint8Array([meta.length>>>8,meta.length&255]),meta,raw);};
const unpackFile=bytes=>{if(bytes.length<5||asText(bytes.slice(0,3))!=='VF1')throw Error('Formato de arquivo interno inválido.');const mlen=(bytes[3]<<8)|bytes[4];if(mlen>10000||5+mlen>bytes.length)throw Error('Metadados do arquivo inválidos.');let m;try{m=JSON.parse(asText(bytes.slice(5,5+mlen)))}catch{throw Error('Metadados do arquivo ilegíveis.')}if(typeof m.n!=='string'||typeof m.m!=='string')throw Error('Metadados inesperados.');return{name:cleanFilename(m.n),mime:m.m,bytes:bytes.slice(5+mlen)};};
const sha256Hex=async bytes=>Array.from(new Uint8Array(await subtle().digest('SHA-256',bytes))).map(x=>x.toString(16).padStart(2,'0')).join('');
function saveBlob(bytes,name,mime='application/octet-stream'){const blob=bytes instanceof Blob?bytes:new Blob([bytes],{type:mime}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=cleanFilename(name);document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
async function copy(value){if(!value)throw Error('Nenhum conteúdo para copiar.');if(navigator.clipboard&&globalThis.isSecureContext){try{await navigator.clipboard.writeText(value);return;}catch{ /* Browser permission can deny clipboard writes on local documents. */ }}const el=document.createElement('textarea');el.value=value;el.style.position='fixed';el.style.left='-9999px';document.body.append(el);el.focus();el.select();const ok=document.execCommand('copy');el.remove();if(!ok)throw Error('A cópia foi bloqueada. Selecione manualmente o texto.');}
async function shareText(value){if(!value)return;const file=new File([value],'mensagem.veil',{type:'text/plain'});if(navigator.canShare?.({files:[file]})&&navigator.share){try{await navigator.share({files:[file],title:'VEIL · Conteúdo criptografado'});return}catch(e){if(e.name==='AbortError')return;}}if(navigator.share){try{await navigator.share({text:value,title:'VEIL · Conteúdo criptografado'});return}catch(e){if(e.name==='AbortError')return;}}await copy(value);inform('Compartilhamento indisponível; código copiado.');}
function setBusy(id,busy){VeilUI.busy(id,busy);}
function showView(name){VeilUI.showView(name);}
function setTab(next){tab=next;for(const t of ['text','file'])$('enc-tab-'+t).setAttribute('aria-selected',String(t===next));$('enc-text-field').classList.toggle('hidden',next!=='text');$('enc-file-field').classList.toggle('hidden',next!=='file');resetEncrypted();}
function updateSummary(){$('enc-summary').textContent=$('enc-suite').value+' · PBKDF2/'+$('enc-kdf').value+' · '+Number($('enc-work').value).toLocaleString('pt-BR')+' iterações';}
function updateSuites(){updateSummary();const suite=$('enc-suite').value,mode=SUITES[suite].mode;const isPQ=mode==='PQ';$('enc-pq-wrap').classList.toggle('hidden',!isPQ);const info={'GCM':'AES-GCM autentica o conteúdo e todos os parâmetros do envelope.','CHACHA':'ChaCha20-Poly1305 requer suporte moderno do WebCrypto; sem fallback silencioso.','OCB':'AES-OCB autentica mensagem e metadados; disponível somente em implementações WebCrypto recentes.','CBC-HMAC':'AES-CBC com HMAC-SHA256 (Encrypt-then-MAC) autentica ciphertext e cabeçalho.','CTR-HMAC':'AES-CTR com HMAC-SHA256 (Encrypt-then-MAC) autentica ciphertext e cabeçalho.','PQ':'Requer chave pública PQPK1., senha forte e suporte ML-KEM neste navegador.'};$('enc-suite-help').textContent=info[mode];if(isPQ){const k=SUITES[suite].kem;$('enc-pq-state').textContent=kemAvailable.get(k)?'Este navegador suporta '+k+'. A senha e a chave privada serão necessárias ao abrir.':'Atenção: '+k+' pode estar indisponível neste navegador. Verifique na aba Chaves.';}}
function strength(p){let score=0;if(p.length>=10)score++;if(p.length>=15)score++;if(p.length>=20)score++;if(/[A-Z]/.test(p)&&/[a-z]/.test(p))score++;if(/[\d\W_]/.test(p))score++;const common=/password|senha|123456|qwerty|admin|iloveyou/i.test(p);if(common)score=Math.min(score,1);if(!p)score=0;const v=Math.min(5,score);$('strength-bar').style.width=(v*20)+'%';$('strength-bar').style.background=v<2?'var(--danger)':v<4?'var(--caution)':'var(--secure)';$('strength-label').textContent=(!p?'Use 12+ caracteres; uma frase-senha longa é melhor.':v<2?'Senha fraca · escolha algo mais longo e único.':v<4?'Senha razoável · aumente o comprimento.':'Boa complexidade aparente · prefira uma frase-senha única.');}
function describeEnvelope(x){return `${x.suite} · ${x.kind==='file'?'Arquivo':x.kind==='private-key'?'Chave privada':'Mensagem'} · ${x.kdf} / ${x.rounds.toLocaleString('pt-BR')} iterações${x.pq?' · chave '+x.pq.kem:''}`;}
function inspect(){const d=detectInput($('dec-input').value),box=$('inspection');if(d.type==='empty'){box.classList.add('hidden');$('dec-pq-wrap').classList.add('hidden');return d;}if(d.type==='veil'){box.textContent='VEIL v1 identificado (metadados ainda não autenticados) · '+describeEnvelope(d.obj);$('dec-pq-wrap').classList.toggle('hidden',!d.obj.pq);}else{box.textContent=d.label;$('dec-pq-wrap').classList.add('hidden');}if(box.classList.contains('hidden'))box.className='notice notice-info is-in';return d;}
async function encryptClick(){hideWarning('enc-alert');resetEncrypted();setBusy('encrypt-btn',true);try{const suite=$('enc-suite').value,password=$('enc-password').value,kdf=$('enc-kdf').value,rounds=Number($('enc-work').value);let content;if(password!==$('enc-password-confirm').value)throw Error('As senhas de proteção não coincidem.');
if(tab==='file'){if(!encryptFile)throw Error('Selecione o arquivo original.');if(encryptFile.size>MAX_FILE)throw Error('Arquivo excede 24 MiB.');content=await packFile(encryptFile);}else{const txt=$('enc-text').value;if(!txt)throw Error('Digite uma mensagem para criptografar.');content=asBytes(txt);if(content.length>MAX_FILE)throw Error('Mensagem excede o limite de tamanho.');}
encryptedOutput=await protect(content,{password,suite,kdf,rounds,kind:tab,pub:$('enc-pq-public').value});encryptedKind=tab;$('enc-sha256').textContent=await sha256Hex(asBytes(encryptedOutput));$('enc-result-suite').textContent=suite;const shown=encryptedOutput.length>4500?encryptedOutput.slice(0,1600)+'\n\n[…] código longo · '+encryptedOutput.length.toLocaleString('pt-BR')+' caracteres · use Salvar .veil para obter o código completo':encryptedOutput;$('enc-placeholder').classList.add('hidden');$('enc-result').classList.remove('hidden');VeilUI.unveil($('enc-result'));VeilUI.settleText($('enc-result-text'),shown);$('enc-result').scrollIntoView({behavior:VeilUI.reduced()?'auto':'smooth',block:'nearest'});
}catch(e){warning('enc-alert',e.message||'Erro ao criptografar.');}finally{setBusy('encrypt-btn',false);}}
async function decryptClick(){hideWarning('dec-alert');resetDecrypted();setBusy('decrypt-btn',true);decryptedOutput=null;let revealText=null;try{const value=$('dec-input').value.trim();const {obj,bytes}=await recover(value,$('dec-password').value,$('dec-pq-private').value,$('dec-pq-pass').value);let restored;if(obj.kind==='file'){restored=unpackFile(bytes);decryptedOutput={kind:'file',...restored};$('dec-result-type').textContent='ARQUIVO VERIFICADO';$('dec-result-text').textContent='Arquivo original: '+restored.name+'\nTamanho: '+restored.bytes.length.toLocaleString('pt-BR')+' bytes\nIntegridade: verificada';$('copy-decrypted').classList.add('hidden');revealText=null;}else{const txt=asText(bytes);decryptedOutput={kind:'text',text:txt};$('dec-result-type').textContent=obj.kind==='private-key'?'CHAVE RESTAURADA':'MENSAGEM VERIFICADA';revealText=txt;$('copy-decrypted').classList.remove('hidden');}
$('dec-placeholder').classList.add('hidden');$('dec-result').classList.remove('hidden');VeilUI.unveil($('dec-result'));if(revealText!==null)VeilUI.settleText($('dec-result-text'),revealText,{toProse:true});$('dec-result').scrollIntoView({behavior:VeilUI.reduced()?'auto':'smooth',block:'nearest'});
}catch(e){warning('dec-alert',e.message||'Não foi possível descriptografar.');}finally{setBusy('decrypt-btn',false);}}
async function keysClick(){hideWarning('key-alert');$('key-output').classList.add('hidden');setBusy('keygen-btn',true);try{if($('key-pass').value!==$('key-pass-confirm').value)throw Error('As senhas da chave privada não coincidem.');const r=await generateKeys($('key-alg').value,$('key-pass').value);$('key-public-output').value=r.pub;$('key-private-output').value=r.priv;$('key-output').classList.remove('hidden');VeilUI.unveil($('key-output'));$('key-output').scrollIntoView({behavior:VeilUI.reduced()?'auto':'smooth',block:'nearest'});warning('key-alert','Par de chaves gerado localmente. Faça backup da chave privada protegida.','success');}catch(e){warning('key-alert',e.message||'Falha ao gerar chaves.')}finally{setBusy('keygen-btn',false)}}
async function refreshCapabilities(){const lines=[],hasCrypto=!!globalThis.crypto?.subtle;lines.push(['WebCrypto',hasCrypto,hasCrypto?'disponível':'indisponível']);lines.push(['Contexto seguro',!!globalThis.isSecureContext,globalThis.isSecureContext?'sim':'não']);lines.push(['WebRTC',!!globalThis.RTCPeerConnection,globalThis.RTCPeerConnection?'disponível':'indisponível']);lines.push(['Leitor de QR nativo','BarcodeDetector' in globalThis,'BarcodeDetector' in globalThis?'disponível':'indisponível']);if(hasCrypto){for(const kem of KEMS){const ok=await pqSupport(kem);lines.push([kem,ok,ok?'KEM funcional':'não disponível']);}let cha=false;try{const key=await subtle().importKey('raw-secret',random(32),{name:'ChaCha20-Poly1305'},false,['encrypt']);await subtle().encrypt({name:'ChaCha20-Poly1305',iv:random(12)},key,asBytes('teste'));cha=true;}catch{}lines.push(['ChaCha20-Poly1305',cha,cha?'disponível':'não disponível']);const chachaOption=$('enc-suite').querySelector('option[value="CHACHA20-POLY1305"]');chachaOption.disabled=!cha;let ocb=false;try{const key=await subtle().importKey('raw-secret',random(32),{name:'AES-OCB'},false,['encrypt']);await subtle().encrypt({name:'AES-OCB',iv:random(12),tagLength:128},key,asBytes('teste'));ocb=true;}catch{}lines.push(['AES-OCB',ocb,ocb?'disponível':'não disponível']);for(const id of ['AES-256-OCB','AES-128-OCB'])$('enc-suite').querySelector('option[value="'+id+'"]').disabled=!ocb;for(const [name,suite] of Object.entries(SUITES)){if(suite.mode==='PQ'){$('enc-suite').querySelector('option[value="'+name+'"]').disabled=!kemAvailable.get(suite.kem);}}}
$('capability').replaceChildren(...lines.map(([name,ok,text])=>{const chip=document.createElement('span');chip.className='cap';chip.dataset.ok=String(Boolean(ok));chip.textContent=name+': '+text;return chip;}));const available=KEMS.some(x=>kemAvailable.get(x));$('pq-chip').textContent=available?'KEM NATIVO VERIFICADO':'SUPORTE NÃO DETECTADO';$('pq-chip').dataset.state=available?'ready':'waiting';$('keygen-btn').disabled=!available;$('key-alg-status').textContent='Suporte: '+KEMS.map(x=>x+' '+(kemAvailable.get(x)?'sim':'não')).join(' · ');for(const x of $('key-alg').options)x.disabled=!kemAvailable.get(x.value);if(available&&!kemAvailable.get($('key-alg').value))$('key-alg').value=KEMS.find(k=>kemAvailable.get(k));updateSuites();}
const resetEncrypted=()=>{encryptedOutput='';$('enc-result').classList.add('hidden');$('enc-result-text').textContent='';$('enc-placeholder').classList.remove('hidden');};
const resetDecrypted=()=>{decryptedOutput=null;$('dec-result').classList.add('hidden');$('dec-result-text').textContent='';$('dec-placeholder').classList.remove('hidden');};
async function selfTestClick(){
 const btn=$('selftest-btn');btn.disabled=true;const target=$('selftest-status');warning('selftest-status','Executando teste local. Nenhum conteúdo de usuário será processado.','info');
 try{
  const message=asBytes('VEIL selftest / UTF-8: açai 🗝️'),password='VEIL-test-password-2026-'+b64(random(16));
  const encrypted=await protect(message,{password,suite:'AES-256-GCM',rounds:100000});
  const recovered=await recover(encrypted,password);if(asText(recovered.bytes)!==asText(message))throw Error('Comparação de bytes falhou.');
  let rejected=false;try{await recover(encrypted,'senha deliberadamente errada');}catch{rejected=true;}if(!rejected)throw Error('Aceitou senha incorreta.');
  const decoded=parseEnvelope(encrypted);decoded.rounds++;
  rejected=false;try{await recover('VEIL1.'+b64(asBytes(JSON.stringify(decoded))),password);}catch{rejected=true;}if(!rejected)throw Error('Aceitou envelope adulterado.');
  warning('selftest-status','PASS · AES-256-GCM, ida e volta UTF-8, senha incorreta rejeitada e cabeçalho adulterado rejeitado. Teste não substitui auditoria independente.','success');
 }catch(e){warning('selftest-status','FALHOU · '+e.message);}finally{btn.disabled=false;}
}
async function mustReject(operation,reason){let rejected=false;try{await operation();}catch{rejected=true;}if(!rejected)throw Error('Não rejeitou '+reason);}
async function pqEndToEnd(alg){if(!KEMS.includes(alg))throw Error('KEM desconhecido.');if(!await pqSupport(alg))throw Error('Algoritmo não disponível.');const keyPassword='Chave-separada-pq-'+b64(random(16)),messagePassword='Mensagem-separada-pq-'+b64(random(16));const pair=await generateKeys(alg,keyPassword,100000);const message=asBytes('VEIL PQ browser test · '+alg+' · á☑️');const suite='PQ-'+alg;const sealed=await protect(message,{password:messagePassword,suite,rounds:100000,pub:pair.pub});const opened=await recover(sealed,messagePassword,pair.priv,keyPassword);if(!equalBytes(opened.bytes,message))throw Error('Texto recuperado não corresponde ao original.');if(opened.obj.pq?.kem!==alg)throw Error('Algoritmo recuperado diverge do selecionado.');await mustReject(()=>recover(sealed,'senha-incorreta-123456',pair.priv,keyPassword),'senha incorreta da mensagem');await mustReject(()=>recover(sealed,messagePassword,pair.priv,'senha-incorreta-123456'),'senha incorreta da chave privada');const obj=parseEnvelope(sealed),capsule=unb64(obj.pq.capsule);capsule[0]^=1;obj.pq.capsule=b64(capsule);await mustReject(()=>recover('VEIL1.'+b64(asBytes(JSON.stringify(obj))),messagePassword,pair.priv,keyPassword),'cápsula adulterada');const ctObj=parseEnvelope(sealed),ciphertext=unb64(ctObj.ct);ciphertext[0]^=1;ctObj.ct=b64(ciphertext);await mustReject(()=>recover('VEIL1.'+b64(asBytes(JSON.stringify(ctObj))),messagePassword,pair.priv,keyPassword),'ciphertext adulterado');return{algorithm:alg,passed:true,checks:7};}
function pqTestRow(name,status,message){const row=document.createElement('div');row.className='pq-line';row.dataset.result=status;const label=document.createElement('strong'),detail=document.createElement('span');label.textContent=status==='pass'?'PASS':status==='skip'?'SEM SUPORTE':status==='fail'?'FALHOU':'TESTANDO';detail.textContent=name+' · '+message;row.append(label,detail);$('pq-browser-results').append(row);return row;}
async function runPqBrowserDiagnostics(){setBusy('pq-browser-button',true);const output=$('pq-browser-results'),state=$('pq-browser-status');output.replaceChildren();const start=performance.now();let passed=0,failed=0,unavailable=0;const engine=navigator.userAgent.match(/(?:Chrome|Chromium|CriOS|Firefox|Version)\/[\d.]+/g)?.join(' · ')||'Navegador não identificado';state.textContent='Executando neste dispositivo · '+engine+' · os dados de teste são descartados ao finalizar.';try{for(const alg of KEMS){let row=pqTestRow(alg,'pending','verificando…');await new Promise(resolve=>setTimeout(resolve,20));const supported=await pqSupport(alg);if(!supported){row.dataset.result='skip';row.firstChild.textContent='SEM SUPORTE';row.lastChild.textContent=alg+' · '+(kemErrors.get(alg)||'WebCrypto ML-KEM indisponível');unavailable++;continue;}try{const result=await pqEndToEnd(alg);row.dataset.result='pass';row.firstChild.textContent='PASS';row.lastChild.textContent=alg+' · geração, importação/exportação, KEM + AES, recuperação e rejeição de quatro tentativas inválidas';passed++;}catch(e){row.dataset.result='fail';row.firstChild.textContent='FALHOU';row.lastChild.textContent=alg+' · '+(e?.message||'Erro desconhecido');failed++;}}const seconds=((performance.now()-start)/1000).toFixed(1);state.textContent=`${passed} aprovado(s) · ${failed} falha(s) · ${unavailable} indisponível(is) · ${seconds} s · ${engine}. ${passed===0&&failed===0?'Os algoritmos não estão disponíveis neste contexto de execução.':'Resultado válido somente para esta sessão e este motor.'} Teste funcional não é auditoria independente.`;}catch(e){state.textContent='Não foi possível concluir: '+(e?.message||'erro de diagnóstico');}finally{setBusy('pq-browser-button',false);}}
let hashTab='text',hashValue='';
function setHashTab(mode){hashTab=mode;for(const type of ['text','file'])$('hash-tab-'+type).setAttribute('aria-selected',String(type===mode));$('hash-text-wrap').classList.toggle('hidden',mode!=='text');$('hash-file-wrap').classList.toggle('hidden',mode!=='file');$('hash-output').classList.add('hidden');hideWarning('hash-result');hashValue='';}
async function runHash(){setBusy('hash-run',true);$('hash-output').classList.add('hidden');hideWarning('hash-result');hashValue='';try{const alg=$('hash-alg').value;if(!['SHA-256','SHA-384','SHA-512'].includes(alg))throw Error('Algoritmo de hash não suportado.');let bytes;if(hashTab==='file'){const file=$('hash-file').files[0];if(!file)throw Error('Selecione um arquivo.');if(file.size>MAX_FILE)throw Error('Arquivo excede o limite de 24 MiB.');bytes=new Uint8Array(await file.arrayBuffer());}else{bytes=asBytes($('hash-text').value);if(bytes.length>MAX_FILE)throw Error('Texto excede o limite de 24 MiB.');}const digest=new Uint8Array(await subtle().digest(alg,bytes));hashValue=Array.from(digest,v=>v.toString(16).padStart(2,'0')).join('');$('hash-value').textContent=hashValue;$('hash-output-alg').textContent=alg;$('hash-output').classList.remove('hidden');VeilUI.unveil($('hash-output'));const expected=$('hash-expected').value.trim().toLowerCase().replace(/[\s:]/g,'');if(expected){if(!/^[a-f0-9]+$/.test(expected)||expected.length!==hashValue.length)throw Error('Hash esperado inválido. Informe '+hashValue.length+' caracteres hexadecimais para '+alg+'.');warning('hash-result',expected===hashValue?'Os hashes são iguais (comparação local).':'Os hashes são diferentes: não correspondem aos mesmos bytes.',expected===hashValue?'success':'error');}else{warning('hash-result','Hash calculado localmente. Nenhum arquivo ou mensagem foi enviado.','info');}}catch(e){warning('hash-result',e.message||'Não foi possível calcular o hash.');}finally{setBusy('hash-run',false);}}

const ONCE_DB='VEIL_LOCAL_ONETIME_V1',ONCE_STORE='secrets',ONCE_MAX_TEXT=100000;
let onceRevealTimer=null,onceRevealLeft=60;
function onceHide(){if(onceRevealTimer){clearInterval(onceRevealTimer);onceRevealTimer=null;}$('once-reveal-text').textContent='';$('once-reveal').classList.add('hidden');onceRevealLeft=60;VeilUI.setRing($('once-ring'),1);}
function onceShow(message){onceHide();$('once-reveal').classList.remove('hidden');VeilUI.unveil($('once-reveal'),760);VeilUI.settleText($('once-reveal-text'),message,{toProse:true});onceRevealLeft=60;$('once-countdown').textContent='60 s';const deadline=Date.now()+60000;requestAnimationFrame(()=>VeilUI.setRing($('once-ring'),59/60));onceRevealTimer=setInterval(()=>{onceRevealLeft=Math.max(0,Math.ceil((deadline-Date.now())/1000));$('once-countdown').textContent=onceRevealLeft+' s';VeilUI.setRing($('once-ring'),Math.max(0,onceRevealLeft-1)/60);if(onceRevealLeft<=0)onceHide();},1000);$('once-reveal').scrollIntoView({behavior:VeilUI.reduced()?'auto':'smooth',block:'nearest'});$('once-reveal').focus({preventScroll:true});}
function openOnceDb(){return new Promise((resolve,reject)=>{if(!globalThis.indexedDB){reject(Error('Este navegador não oferece IndexedDB.'));return;}let req;try{req=indexedDB.open(ONCE_DB,1);}catch(e){reject(e);return;}req.onupgradeneeded=()=>{if(!req.result.objectStoreNames.contains(ONCE_STORE))req.result.createObjectStore(ONCE_STORE,{keyPath:'id'});};req.onerror=()=>reject(req.error||Error('Falha ao abrir IndexedDB.'));req.onsuccess=()=>resolve(req.result);req.onblocked=()=>reject(Error('Feche outras abas VEIL para atualizar o cofre.'));});}
async function onceDbTx(mode,fn){const db=await openOnceDb();return new Promise((resolve,reject)=>{let settled=false,result;const tx=db.transaction(ONCE_STORE,mode),store=tx.objectStore(ONCE_STORE);tx.oncomplete=()=>{db.close();if(!settled){settled=true;resolve(result);}};tx.onerror=()=>{db.close();if(!settled){settled=true;reject(tx.error||Error('Transação do cofre falhou.'));}};tx.onabort=()=>{db.close();if(!settled){settled=true;reject(tx.error||Error('Transação cancelada.'));}};try{fn(store,(value)=>{result=value},(request)=>{request.onerror=()=>{try{tx.abort()}catch{}};});}catch(e){try{tx.abort()}catch{};if(!settled){settled=true;reject(e);}}});}
function onceDbRead(id){return onceDbTx('readonly',(store,set)=>{const req=store.get(id);req.onsuccess=()=>set(req.result||null);});}
function onceDbList(){return onceDbTx('readonly',(store,set)=>{const req=store.getAll();req.onsuccess=()=>set(req.result||[]);});}
function onceDbPut(item){return onceDbTx('readwrite',(store)=>{store.put(item);});}
function onceDbDelete(id,expected){return onceDbTx('readwrite',(store,set)=>{const req=store.get(id);req.onsuccess=()=>{const existing=req.result;if(!existing||existing.envelope!==expected){set(false);return;}store.delete(id);set(true);};});}
function onceNormalId(value){const val=String(value||'').trim();const id=val.startsWith('VL1.')?val.slice(4):val;if(!/^[A-Za-z0-9_-]{16}$/.test(id))throw Error('Identificador local inválido.');return id;}
async function onceRefresh(){const node=$('once-local-list');node.replaceChildren();try{const entries=(await onceDbList()).sort((a,b)=>b.created-a.created);if(!entries.length){const p=document.createElement('p');p.className='hint';p.textContent='Nenhuma mensagem armazenada neste navegador.';node.append(p);return;}for(const item of entries){const expired=item.expires<=Date.now(),row=document.createElement('div');row.className='once-item';const left=document.createElement('div'),code=document.createElement('code');code.textContent='VL1.'+item.id;const more=document.createElement('small');more.textContent=(expired?'Expirada · será apagada ao tentar abrir':'Expira: '+new Date(item.expires).toLocaleString('pt-BR'))+' · somente neste navegador';left.append(code,more);const btn=document.createElement('button');btn.type='button';btn.className='btn btn-sm';btn.textContent='Selecionar';btn.addEventListener('click',()=>{$('once-local-id').value='VL1.'+item.id;$('once-local-open-pass').focus();});row.append(left,btn);node.append(row);}}catch(e){const p=document.createElement('p');p.className='hint';p.textContent='Armazenamento local indisponível: '+e.message;node.append(p);}}
async function onceCreateLocal(){hideWarning('once-local-alert');setBusy('once-local-create',true);try{const plain=$('once-local-text').value,pass=$('once-local-pass').value;if(!plain)throw Error('Digite uma mensagem.');if(plain.length>ONCE_MAX_TEXT)throw Error('Mensagem muito longa.');if(pass!==$('once-local-confirm').value)throw Error('As senhas não coincidem.');const envelope=await protect(asBytes(plain),{password:pass,suite:'AES-256-GCM',rounds:600000});const id=b64(random(12));const created=Date.now(),expires=created+Number($('once-local-expire').value);await onceDbPut({id,created,expires,envelope});$('once-local-text').value='';$('once-local-pass').value='';$('once-local-confirm').value='';$('once-local-id').value='VL1.'+id;warning('once-local-alert','Mensagem guardada. O identificador já está preenchido em “Abrir e apagar”. Ele só funciona neste navegador.','success');await onceRefresh();}catch(e){warning('once-local-alert',e.message||'Não foi possível guardar a mensagem.');}finally{setBusy('once-local-create',false);}}
async function onceOpenLocal(){hideWarning('once-local-open-alert');setBusy('once-local-open',true);onceHide();try{const id=onceNormalId($('once-local-id').value),pass=$('once-local-open-pass').value;const record=await onceDbRead(id);if(!record)throw Error('Mensagem já consumida, inexistente ou não presente neste navegador.');if(Date.now()>=record.expires){await onceDbDelete(id,record.envelope);throw Error('A validade terminou. O registro expirado foi descartado.');}const decrypted=await recover(record.envelope,pass);const message=asText(decrypted.bytes);const burned=await onceDbDelete(id,record.envelope);if(!burned)throw Error('O registro já foi consumido em outra aba. O texto não será revelado.');$('once-local-open-pass').value='';$('once-local-id').value='';warning('once-local-open-alert','Registro apagado do cofre antes da exibição. A visualização será ocultada em 60 segundos.','success');onceShow(message);await onceRefresh();}catch(e){warning('once-local-open-alert',e.message||'Não foi possível abrir.');await onceRefresh();}finally{setBusy('once-local-open',false);}}

const wire=()=>{
VeilUI.onView(name=>{if(name!=='once')onceHide();});
$('enc-tab-text').addEventListener('click',()=>setTab('text'));$('enc-tab-file').addEventListener('click',()=>setTab('file'));
$('enc-suite').addEventListener('change',()=>{updateSuites();resetEncrypted();});$('enc-password').addEventListener('input',e=>{strength(e.target.value);resetEncrypted();});
$('gen-password').addEventListener('click',()=>{const alph='ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789!@#$%^&*_-+=';let generated='';const ceiling=256-(256%alph.length);while(generated.length<32){for(const n of random(48)){if(n<ceiling)generated+=alph[n%alph.length];if(generated.length===32)break}}$('enc-password').value=generated;$('enc-password-confirm').value=generated;resetEncrypted();strength($('enc-password').value);inform('Senha aleatória criada. Salve-a em um gerenciador de senhas.');});
document.querySelectorAll('.toggle-password').forEach(b=>b.addEventListener('click',()=>{const x=$(b.dataset.target);x.type=x.type==='password'?'text':'password';const shown=x.type==='text';b.setAttribute('aria-pressed',String(shown));b.setAttribute('aria-label',b.getAttribute('aria-label').replace(shown?/^Mostrar/:/^Ocultar/,shown?'Ocultar':'Mostrar'));}));
function chooseFile(file){if(!file)return;encryptFile=file;$('enc-drop').classList.add('has-file');$('enc-file-name').textContent=file.name;$('enc-file-info').textContent=(file.size/1024/1024).toFixed(2)+' MiB · '+(file.type||'tipo desconhecido');resetEncrypted();if(file.size>MAX_FILE)warning('enc-alert','Arquivo excede 24 MiB.');}
$('enc-file').addEventListener('change',e=>chooseFile(e.target.files[0]));const drop=$('enc-drop');for(const type of ['dragenter','dragover'])drop.addEventListener(type,e=>{e.preventDefault();drop.classList.add('drag')});for(const type of ['dragleave','drop'])drop.addEventListener(type,e=>{e.preventDefault();drop.classList.remove('drag')});drop.addEventListener('drop',e=>chooseFile(e.dataTransfer?.files?.[0]));
$('encrypt-btn').addEventListener('click',encryptClick);$('decrypt-btn').addEventListener('click',decryptClick);$('keygen-btn').addEventListener('click',keysClick);$('pq-browser-button').addEventListener('click',runPqBrowserDiagnostics);$('selftest-btn').addEventListener('click',selfTestClick);$('copy-digest').addEventListener('click',()=>copy($('enc-sha256').textContent).then(()=>inform('SHA-256 copiado.')).catch(e=>warning('enc-alert',e.message)));
 for(const id of ['enc-text','enc-pq-public','enc-password-confirm','enc-kdf','enc-work'])$(id).addEventListener(['enc-text','enc-pq-public','enc-password-confirm'].includes(id)?'input':'change',resetEncrypted);for(const id of ['enc-kdf','enc-work'])$(id).addEventListener('change',updateSummary);for(const id of ['dec-password','dec-pq-private','dec-pq-pass'])$(id).addEventListener('input',resetDecrypted);
$('enc-clear').addEventListener('click',()=>{encryptFile=null;$('enc-drop').classList.remove('has-file');$('enc-file').value='';$('enc-file-name').textContent='Clique para selecionar ou arraste um arquivo';$('enc-file-info').textContent='Até 24 MiB · qualquer formato';$('enc-text').value='';$('enc-password').value='';$('enc-password-confirm').value='';$('enc-pq-public').value='';strength('');hideWarning('enc-alert');resetEncrypted();});
$('dec-clear').addEventListener('click',()=>{$('dec-input').value='';$('dec-password').value='';$('dec-file').value='';$('dec-pq-private').value='';$('dec-pq-pass').value='';$('inspection').classList.add('hidden');$('dec-pq-wrap').classList.add('hidden');resetDecrypted();hideWarning('dec-alert');});
$('dec-input').addEventListener('input',()=>{inspect();resetDecrypted()});$('inspect-btn').addEventListener('click',()=>{inspect();inform('Análise local concluída.');});$('dec-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;if(file.size>MAX_ENVELOPE) {warning('dec-alert','Envelope excede o limite suportado.');return;}try{$('dec-input').value=await file.text();inspect();resetDecrypted();hideWarning('dec-alert');}catch{warning('dec-alert','Falha ao abrir o arquivo.')}});
$('copy-encrypted').addEventListener('click',async e=>{try{await copy(encryptedOutput);VeilUI.confirmLabel(e.currentTarget,'Copiado');inform('Código completo copiado.')}catch(e){warning('enc-alert',e.message)}});
$('download-encrypted').addEventListener('click',()=>{if(encryptedOutput)saveBlob(encryptedOutput,encryptedKind==='file'?'arquivo-protegido.veil':'mensagem.veil','text/plain;charset=utf-8')});
$('share-encrypted').addEventListener('click',async()=>{try{await shareText(encryptedOutput)}catch(e){warning('enc-alert',e.message)}});
$('move-to-decrypt').addEventListener('click',()=>{$('dec-input').value=encryptedOutput;showView('decrypt');$('dec-password').value=$('enc-password').value;resetDecrypted();inspect();});
$('copy-decrypted').addEventListener('click',async e=>{if(!decryptedOutput||decryptedOutput.kind!=='text')return;try{await copy(decryptedOutput.text);VeilUI.confirmLabel(e.currentTarget,'Copiada');inform('Mensagem copiada.')}catch(e){warning('dec-alert',e.message)}});
$('download-decrypted').addEventListener('click',()=>{if(!decryptedOutput)return;if(decryptedOutput.kind==='file')saveBlob(decryptedOutput.bytes,decryptedOutput.name,decryptedOutput.mime);else saveBlob(decryptedOutput.text,'mensagem-recuperada.txt','text/plain;charset=utf-8');});
$('key-pub-copy').addEventListener('click',async e=>{try{await copy($('key-public-output').value);VeilUI.confirmLabel(e.currentTarget,'Copiada');inform('Chave pública copiada.')}catch(e){warning('key-alert',e.message)}});
$('key-priv-copy').addEventListener('click',async()=>{try{await copy($('key-private-output').value);inform('Chave privada protegida copiada.')}catch(e){warning('key-alert',e.message)}});
$('key-pub-save').addEventListener('click',()=>saveBlob($('key-public-output').value,'chave-publica-pq.txt','text/plain'));
$('key-priv-save').addEventListener('click',()=>saveBlob($('key-private-output').value,'CHAVE-PRIVADA-protegida.txt','text/plain'));
$('hash-tab-text').addEventListener('click',()=>setHashTab('text'));
$('hash-tab-file').addEventListener('click',()=>setHashTab('file'));
$('hash-run').addEventListener('click',runHash);
$('hash-clear').addEventListener('click',()=>{$('hash-text').value='';$('hash-file').value='';$('hash-expected').value='';$('hash-output').classList.add('hidden');hideWarning('hash-result');hashValue='';});
for(const id of ['hash-text','hash-expected','hash-file','hash-alg'])$(id).addEventListener(['hash-text','hash-expected'].includes(id)?'input':'change',()=>{$('hash-output').classList.add('hidden');hideWarning('hash-result');hashValue='';});
$('hash-copy').addEventListener('click',async e=>{try{await copy(hashValue);VeilUI.confirmLabel(e.currentTarget,'Copiado');inform('Hash copiado.')}catch(e){warning('hash-result',e.message)}});
$('once-local-create').addEventListener('click',onceCreateLocal);
$('once-local-open').addEventListener('click',onceOpenLocal);
$('once-local-refresh').addEventListener('click',onceRefresh);
$('once-close').addEventListener('click',onceHide);
document.addEventListener('visibilitychange',()=>{if(document.hidden)onceHide();});window.addEventListener('pagehide',onceHide);
$('format-detect').addEventListener('click',()=>{const d=detectInput($('format-input').value);$('format-result').textContent=d.type==='veil'?'VEIL v1 encontrado · '+describeEnvelope(d.obj):d.label;$('format-result').className='notice notice-info is-in';});
$('format-clear').addEventListener('click',()=>{$('format-input').value='';$('format-result').classList.add('hidden');});
$('format-input').addEventListener('input',()=>{$('format-result').classList.add('hidden');});
$('key-alg').addEventListener('change',()=>{const k=$('key-alg').value;$('key-alg-status').textContent=kemAvailable.get(k)?'KEM testado neste navegador (use o teste completo abaixo).':'Indisponível neste navegador.';});
};wire();onceRefresh();updateSuites();refreshCapabilities().catch(e=>{$('capability').textContent='Não foi possível verificar recursos: '+e.message;$('pq-chip').textContent='INDISPONÍVEL';$('keygen-btn').disabled=true;});
})();
